package sdk

import (
	"encoding/json"
	"fmt"
	"strings"
)

const diffContextLines = 3

// DryRunSummaryPrefix is the optional stderr line prefix plugins can emit to
// provide a structured machine-readable summary for `semrel release --dry-run --output json`.
const DryRunSummaryPrefix = "plugin_dry_run_summary="

// UnifiedDiff computes a unified diff between before and after for the given
// file path entirely in memory. When before and after are identical, it returns
// an empty string.
func UnifiedDiff(path, before, after string) string {
	if before == after {
		return ""
	}
	cleanPath := strings.TrimPrefix(strings.ReplaceAll(path, "\\", "/"), "./")
	if cleanPath == "" {
		cleanPath = "file"
	}

	aLines := splitLines(before)
	bLines := splitLines(after)
	ops := diffLines(aLines, bLines)
	hunks := buildHunks(ops, diffContextLines)
	if len(hunks) == 0 {
		return ""
	}

	var b strings.Builder
	fmt.Fprintf(&b, "--- a/%s\n+++ b/%s\n", cleanPath, cleanPath)
	for _, h := range hunks {
		fmt.Fprintf(&b, "@@ -%d,%d +%d,%d @@\n", h.aStart, h.aCount, h.bStart, h.bCount)
		for _, line := range h.lines {
			b.WriteString(line)
			b.WriteByte('\n')
		}
	}
	return b.String()
}

// UnifiedDiffBytes computes a unified diff between two byte slices in memory.
func UnifiedDiffBytes(path string, before, after []byte) string {
	return UnifiedDiff(path, string(before), string(after))
}

// MaskSecret masks a secret string or webhook token for safe dry-run output.
func MaskSecret(value string) string {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return ""
	}
	if len(trimmed) <= 8 {
		return "***"
	}
	return trimmed[:4] + "***"
}

// FormatDryRunSummary encodes a structured dry-run summary line suitable for
// writing to stderr.
func FormatDryRunSummary(summary map[string]interface{}) string {
	if len(summary) == 0 {
		return ""
	}
	data, err := json.Marshal(summary)
	if err != nil {
		return ""
	}
	return DryRunSummaryPrefix + string(data)
}

type editOp struct {
	kind byte // ' ', '-', '+'
	text string
	aIdx int
	bIdx int
}

type diffHunk struct {
	aStart int
	aCount int
	bStart int
	bCount int
	lines  []string
}

func splitLines(s string) []string {
	if s == "" {
		return nil
	}
	normalized := strings.ReplaceAll(s, "\r\n", "\n")
	normalized = strings.TrimSuffix(normalized, "\n")
	if normalized == "" {
		return []string{""}
	}
	return strings.Split(normalized, "\n")
}

func diffLines(a, b []string) []editOp {
	n, m := len(a), len(b)
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}
	for i := n - 1; i >= 0; i-- {
		for j := m - 1; j >= 0; j-- {
			if a[i] == b[j] {
				dp[i][j] = dp[i+1][j+1] + 1
			} else if dp[i+1][j] >= dp[i][j+1] {
				dp[i][j] = dp[i+1][j]
			} else {
				dp[i][j] = dp[i][j+1]
			}
		}
	}

	ops := make([]editOp, 0, n+m)
	i, j := 0, 0
	for i < n && j < m {
		if a[i] == b[j] {
			ops = append(ops, editOp{kind: ' ', text: a[i], aIdx: i + 1, bIdx: j + 1})
			i++
			j++
		} else if dp[i+1][j] >= dp[i][j+1] {
			ops = append(ops, editOp{kind: '-', text: a[i], aIdx: i + 1, bIdx: j + 1})
			i++
		} else {
			ops = append(ops, editOp{kind: '+', text: b[j], aIdx: i + 1, bIdx: j + 1})
			j++
		}
	}
	for i < n {
		ops = append(ops, editOp{kind: '-', text: a[i], aIdx: i + 1, bIdx: j + 1})
		i++
	}
	for j < m {
		ops = append(ops, editOp{kind: '+', text: b[j], aIdx: i + 1, bIdx: j + 1})
		j++
	}
	return ops
}

func buildHunks(ops []editOp, contextLines int) []diffHunk {
	type span struct{ start, end int }
	var changes []span
	for idx, op := range ops {
		if op.kind == ' ' {
			continue
		}
		s := idx - contextLines
		if s < 0 {
			s = 0
		}
		e := idx + contextLines + 1
		if e > len(ops) {
			e = len(ops)
		}
		if len(changes) > 0 && s <= changes[len(changes)-1].end {
			changes[len(changes)-1].end = e
		} else {
			changes = append(changes, span{start: s, end: e})
		}
	}

	hunks := make([]diffHunk, 0, len(changes))
	for _, ch := range changes {
		slice := ops[ch.start:ch.end]
		h := diffHunk{
			aStart: 1,
			bStart: 1,
			lines:  make([]string, 0, len(slice)),
		}
		if len(slice) > 0 {
			h.aStart = slice[0].aIdx
			h.bStart = slice[0].bIdx
		}
		for _, op := range slice {
			switch op.kind {
			case ' ':
				h.aCount++
				h.bCount++
			case '-':
				h.aCount++
			case '+':
				h.bCount++
			}
			h.lines = append(h.lines, string(op.kind)+op.text)
		}
		if h.aCount == 0 {
			h.aStart = 0
		}
		if h.bCount == 0 {
			h.bStart = 0
		}
		hunks = append(hunks, h)
	}
	return hunks
}
